<?php
declare(strict_types=1);namespace NpmGateway\Http\Controllers;
use NpmGateway\Contracts\CorporateToolsProviderInterface;use NpmGateway\Exceptions\Domain\CommunityActionPropertyForbiddenException;use NpmGateway\Exceptions\Domain\CommunityActionPropertyNotFoundException;use NpmGateway\Exceptions\Domain\InvalidCreditCardPurchaseException;use NpmGateway\Http\AuthenticatedRequestContext;use NpmGateway\Http\Request;use NpmGateway\Http\Response;use NpmGateway\Security\CsrfService;use NpmGateway\Services\CommunityActionContextResolver;use NpmGateway\Services\CreditCardPurchaseService;use NpmGateway\Services\GatewayStorageService;use NpmGateway\Support\FlashSession;
final class CreditCardPurchaseController{public function __construct(private readonly CommunityActionContextResolver $resolver,private readonly CreditCardPurchaseService $service,private readonly GatewayStorageService $storage,private readonly CorporateToolsProviderInterface $tools,private readonly CsrfService $csrf,private readonly FlashSession $flash,private readonly string $views){}
 public function index(Request $r,string $slug,AuthenticatedRequestContext $request):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;$search=trim((string)($r->query['search']??''));$requestedReceipt=trim((string)($r->query['receipt_status']??''));$receipt=in_array($requestedReceipt,['attached','missing'],true)?$requestedReceipt:'';$filtersActive=$search!==''||$receipt!=='';$purchases=$this->service->list($c->propertyId,$search,$receipt);$summary=$this->service->summary($c->propertyId,$search,$receipt);$success=(string)$this->flash->pull('cc_purchase_success','');return $this->render('index',$request,compact('c','search','receipt','filtersActive','purchases','summary','success'));}
 public function create(string $slug,AuthenticatedRequestContext $request):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;$input=(array)$this->flash->pull('cc_purchase_input',[]);$errors=(array)$this->flash->pull('cc_purchase_errors',[]);$employees=$this->service->eligibleEmployees($c->propertyId);return $this->render('create',$request,compact('c','input','errors','employees'));}
 public function store(Request $r,string $slug,AuthenticatedRequestContext $request):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.',['Cache-Control'=>'private, no-store']);try{$result=$this->service->post($c,$r->post,$r->files);$this->flash->put('cc_purchase_success',$result['receipt_status']==='missing'?'Credit card purchase posted. Receipt documentation is marked missing.':'Credit card purchase posted successfully.');return Response::redirect('/community-actions/'.$c->propertySlug.'/credit-card-purchases/'.$result['public_id']);}catch(InvalidCreditCardPurchaseException $e){$this->flash->put('cc_purchase_input',$e->input);$this->flash->put('cc_purchase_errors',$e->errors);return Response::redirect('/community-actions/'.$c->propertySlug.'/credit-card-purchases/create');}catch(CommunityActionPropertyForbiddenException){return new Response(403,'Forbidden',['Cache-Control'=>'private, no-store']);}catch(\Throwable){return new Response(500,'The credit card purchase could not be saved safely.',['Cache-Control'=>'private, no-store']);}}
 public function show(string $slug,string $public,AuthenticatedRequestContext $request):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;$purchase=$this->service->detail($public,$c->propertyId);if(!$purchase)return new Response(404,'Not Found',['Cache-Control'=>'private, no-store']);$success=(string)$this->flash->pull('cc_purchase_success','');$error=(string)$this->flash->pull('cc_purchase_error','');return $this->render('show',$request,compact('c','purchase','success','error'));}
 public function uploadReceipt(Request $r,string $slug,string $public,AuthenticatedRequestContext $request):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.',['Cache-Control'=>'private, no-store']);try{$this->service->addReceipt($c,$public,(array)($r->files['receipt']??[]));$this->flash->put('cc_purchase_success','Receipt uploaded successfully.');}catch(\Throwable $e){$this->flash->put('cc_purchase_error',$e instanceof \InvalidArgumentException?$e->getMessage():'The receipt could not be uploaded safely.');}return Response::redirect('/community-actions/'.$c->propertySlug.'/credit-card-purchases/'.$public);}
 public function viewReceipt(string $slug,string $purchasePublic,string $receiptPublic,AuthenticatedRequestContext $request):Response{return $this->documentResponse($slug,$purchasePublic,$receiptPublic,$request,false);}
 public function downloadReceipt(string $slug,string $purchasePublic,string $receiptPublic,AuthenticatedRequestContext $request):Response{return $this->documentResponse($slug,$purchasePublic,$receiptPublic,$request,true);} public function receipt(string $slug,string $public,AuthenticatedRequestContext $request):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;$purchase=$this->service->detail($public,$c->propertyId);$object=$purchase?$this->service->publishedReceipt($purchase):null;if(!$object||!$this->storage->available($object))return new Response(404,'Not Found',['Cache-Control'=>'private, no-store']);$name=preg_replace('/[^A-Za-z0-9._ -]/','_',basename((string)$object['display_filename']))?:'receipt';return new Response(200,'',['Content-Type'=>(string)$object['mime_type'],'Content-Disposition'=>'inline; filename="'.addcslashes($name,'"\\').'"','X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store'],[],$this->storage->open($object));}
 private function documentResponse(string $slug,string $purchasePublic,string $receiptPublic,AuthenticatedRequestContext $request,bool $download):Response{if(($c=$this->context($request,$slug))instanceof Response)return $c;$document=$this->service->receiptDocument($purchasePublic,$receiptPublic,$c->propertyId);if(!$document)return new Response(404,'Not Found',['Cache-Control'=>'private, no-store']);$mime=(string)$document['mime_type'];if(!in_array($mime,['application/pdf','image/jpeg','image/png'],true))return new Response(415,'This file type cannot be displayed in Gateway.',['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);$object=$this->service->publishedReceipt(['storage_public_id'=>$document['storage_public_id']]);if(!$object||!$this->storage->available($object))return new Response(404,'Not Found',['Cache-Control'=>'private, no-store']);$name=preg_replace('/[^A-Za-z0-9._ -]/','_',basename((string)$document['display_filename']))?:'document';$disposition=$download?'attachment':'inline';return new Response(200,'',['Content-Type'=>$mime,'Content-Disposition'=>$disposition.'; filename="'.addcslashes($name,'"\\').'"','Content-Length'=>(string)(int)$document['byte_size'],'Cache-Control'=>'private, no-store','Pragma'=>'no-cache','X-Content-Type-Options'=>'nosniff','Cross-Origin-Resource-Policy'=>'same-origin','Content-Security-Policy'=>"default-src 'none'; frame-ancestors 'self'"],[],$this->storage->open($object));} private function context(AuthenticatedRequestContext $r,string $slug):mixed{try{return $this->resolver->resolve($r,$slug);}catch(CommunityActionPropertyNotFoundException){return new Response(404,'Not Found',['Cache-Control'=>'private, no-store']);}catch(CommunityActionPropertyForbiddenException){return new Response(403,'Forbidden',['Cache-Control'=>'private, no-store']);}}
 private function render(string $view,AuthenticatedRequestContext $request,array $vars):Response{$user=$request->user;$csrfToken=$this->csrf->token();$logoutCsrfToken=$csrfToken;$navbarCorporateItems=$this->tools->tools($request);extract($vars,EXTR_SKIP);ob_start();require $this->views.'/community-actions/credit-card-purchases/'.$view.'.php';return new Response(200,(string)ob_get_clean(),['Cache-Control'=>'private, no-store']);}
}
